protected static int luhn(String s) {
	int sum = 0;
	boolean dbl = true;
	for (int i = s.length() - 1; i >= 0; i--) {
		char c = s.charAt(i);
		if (c < '0' || c > '9') {
			continue;
		}
		int d = c - '0';
		if (dbl) {
